frame.store("_e_kept_before_ing", { let __signature_511 = Signature { name: "_e_kept_before_ing".into(), positional: vec!["word".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_513 = Value::dict(); __attrs_513.dict_set(Value::from("__doc__"), Value::from("The word an e kept before -ing would make: \"moveing\" -> \"moving\", \"takeing\" -> \"taking\".\n\n    A verb that ends in an e drops it before the ending, and a fast typist writes it anyway.\n    Only this ending is tried, because it is the one where the letter before the e decides\n    whether the e stays (\"seeing\", \"freeing\", \"canoeing\" all keep it) and that is a rule the\n    reader cannot hear - so the candidate has to be a word the lexicon knows and it has to be\n    the only one. The four real words that do keep the e are named above.\n    "))?; __attrs_513.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_514 = Value::dict(); __attrs_513.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_510 = Frame::module(frame.globals.clone()); let mut __function_512 = NativeFunction::qualified_with_origin("_e_kept_before_ing".into(), "_e_kept_before_ing".into(), "bot.understanding.normalize".into(), __attrs_513, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/understanding/normalize.py", first: 571, last: 583, qualname: "_e_kept_before_ing" }, closure: __closure_510.clone(), freevars: vec![] }, move |rt, args| __py_21::_e_kept_before_ing(rt, __closure_510.clone(), &__signature_511, args)); __function_512 })?;
