frame.store("_words_the_bot_writes", { let __signature_533 = Signature { name: "_words_the_bot_writes".into(), positional: vec![], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_535 = Value::dict(); __attrs_535.dict_set(Value::from("__doc__"), Value::from("Every word the knowledge base's own keys and answers use, worked out once.\n\n    The guard on a swapped pair is \"only read a word the reader does not know as a word\", and\n    LEXICON cannot answer that on its own: it is the base words and the forms made from them, not\n    a dictionary, so \"stain\", \"order\", \"paper\", \"spilt\" and \"matters\" are not in it and each is\n    one swap from a word it does hold (\"satin\", \"roder\", \"apper\", \"split\", \"mattres\"). Read that\n    way, the reader bent 138 of the deck's own lines.\n\n    The knowledge base cannot make that mistake: its keys and answers are written by the bot, so\n    every word in them is well spelled by construction - the same reasoning `tools/typo_scan.py`\n    gives for scanning them. Asking it is a lazy import because the answer modules import it\n    anyway, and the result is held: one build a process, about a second, and nothing after that.\n    "))?; __attrs_535.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_536 = Value::dict(); __attrs_535.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_532 = Frame::module(frame.globals.clone()); let mut __function_534 = NativeFunction::qualified_with_origin("_words_the_bot_writes".into(), "_words_the_bot_writes".into(), "bot.understanding.normalize".into(), __attrs_535, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/understanding/normalize.py", first: 652, last: 684, qualname: "_words_the_bot_writes" }, closure: __closure_532.clone(), freevars: vec![] }, move |rt, args| __py_24::_words_the_bot_writes(rt, __closure_532.clone(), &__signature_533, args)); __function_534 })?;
