frame.store("_ends_a_state", { let __default_806 = Value::Bool(false); let __signature_804 = Signature { name: "_ends_a_state".into(), positional: vec!["after".into(),"opening".into()], positional_only: 0, defaults: vec![__default_806], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_807 = Value::dict(); __attrs_807.dict_set(Value::from("__doc__"), Value::from("True when what follows a state is where a state can end: nothing, a function word, a time.\n\n    `opening` is for the word that opens a line: there is nothing in front of it to say a state is\n    what the line is about, so a word that a thing can be followed by (\"nappy after nappy\") is not\n    taken as the end of one.\n    "))?; __attrs_807.dict_set(Value::from("__defaults__"), Value::tuple(__signature_804.defaults.clone()))?; let __kwdefaults_808 = Value::dict(); __attrs_807.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_803 = Frame::module(frame.globals.clone()); let mut __function_805 = NativeFunction::qualified_with_origin("_ends_a_state".into(), "_ends_a_state".into(), "bot.understanding.normalize".into(), __attrs_807, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/understanding/normalize.py", first: 1527, last: 1539, qualname: "_ends_a_state" }, closure: __closure_803.clone(), freevars: vec![] }, move |rt, args| __py_51::_ends_a_state(rt, __closure_803.clone(), &__signature_804, args)); __function_805 })?;
frame.store("_opens_a_state", { let __signature_810 = Signature { name: "_opens_a_state".into(), positional: vec!["after".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_812 = Value::dict(); __attrs_812.dict_set(Value::from("__doc__"), Value::from("True when what follows a word that opens a line is a state rather than a thing.\n\n    A state that opens a line is the whole of what they said (\"exausted\", \"exausted from work\",\n    \"worrid about money\", \"nackered all the time\"), so it is repaired; a word that opens a line\n    and is followed by a thing is part of that thing, so it is not (\"nappy cream\", \"nappy rash\",\n    \"nappy change\", \"nappy bag\", \"nappy bin\"). Only the word right after it decides, and every\n    function word - a preposition, a joiner, a time word, a determiner - says the line is about a\n    state, so the list of things does not have to be written down.\n\n    A word that says when is not one of those, because a thing is followed by one as easily as a\n    state is: \"nappy yesterday\" is a nappy, and the line would have to say a state some other way\n    (\"i was nackered yesterday\") before the word is read as one.\n    "))?; __attrs_812.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_813 = Value::dict(); __attrs_812.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_809 = Frame::module(frame.globals.clone()); let mut __function_811 = NativeFunction::qualified_with_origin("_opens_a_state".into(), "_opens_a_state".into(), "bot.understanding.normalize".into(), __attrs_812, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/understanding/normalize.py", first: 1542, last: 1556, qualname: "_opens_a_state" }, closure: __closure_809.clone(), freevars: vec![] }, move |rt, args| __py_52::_opens_a_state(rt, __closure_809.clone(), &__signature_810, args)); __function_811 })?;
frame.store("_a_measure_spelt_wrong", { let __signature_815 = Signature { name: "_a_measure_spelt_wrong".into(), positional: vec!["word".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_817 = Value::dict(); __attrs_817.dict_set(Value::from("__doc__"), Value::from("True when this is a measure word spelt wrong (\"completey exausted\", \"absolutley terified\").\n\n    The measure words are ordinary words, so a slip in one of them is repaired anywhere; this is\n    only about the frame, which cannot see that the word in front of a state is still a measure\n    word with a letter missing. Only words long enough to be no other word with one letter\n    different, so \"realy\" and \"completly\" count and \"to\" and \"so\" do not.\n\n    The closed list is not the whole story, because the \"-ly\" is what says a word measures a state\n    (`_measures_a_state`) and the words in the list above are the ones people say, not the ones\n    they type. A slip that breaks the ending is then in neither: `absolutley`, `extremley`,\n    `genuinly` and `realy` are none of them one letter from a word of the list, and none of them\n    ends in \"ly\" any more, so `im absolutley terified` lost the feeling the spelled line keeps.\n\n    The ending itself is what gets typed wrong, and it is typed wrong in one of two ways: the \"l\"\n    and the \"y\" of \"-ly\" in the wrong order (\"absolutley\", \"extremley\") or a doubled \"l\" typed\n    once (\"totaly\", \"realy\"). Both leave a word ending in \"y\" with a single \"l\" among its last\n    three letters, which no other long word has - \"safety\", \"memory\", \"quality\", \"mouldy\",\n    \"floppy\", \"turkey\" all end in a letter that is not the \"l\" of the ending, and the short words\n    that do (\"barley\", \"parsley\", \"trolley\") are shorter than an adverb of that shape. The adverb\n    itself is often not in the vocabulary at all (\"absolutely\", \"extremely\" are made by an ending\n    rule rather than written down, and their stem is not either), so it is the shape of the ending\n    that is read, and no list of adverbs is asked for and none is kept.\n    "))?; __attrs_817.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_818 = Value::dict(); __attrs_817.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_814 = Frame::module(frame.globals.clone()); let mut __function_816 = NativeFunction::qualified_with_origin("_a_measure_spelt_wrong".into(), "_a_measure_spelt_wrong".into(), "bot.understanding.normalize".into(), __attrs_817, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/understanding/normalize.py", first: 1559, last: 1592, qualname: "_a_measure_spelt_wrong" }, closure: __closure_814.clone(), freevars: vec![] }, move |rt, args| __py_53::_a_measure_spelt_wrong(rt, __closure_814.clone(), &__signature_815, args)); __function_816 })?;
frame.store("_measures_a_state", { let __default_822 = Value::Bool(false); let __signature_820 = Signature { name: "_measures_a_state".into(), positional: vec!["word".into(),"wide".into()], positional_only: 0, defaults: vec![__default_822], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_823 = Value::dict(); __attrs_823.dict_set(Value::from("__doc__"), Value::from("True when this word only says how much or how, not what.\n\n    The measure words are a closed list of the ones people type (\"so\", \"very\", \"not\", \"dead\",\n    \"proper\"), and any word made into an adverb with \"-ly\": \"im absolutely exausted\", \"im\n    literally exausted\", \"im utterly exausted\" are the same state as \"im exausted\", and a list\n    of intensifiers is a list somebody has to keep adding to (lilac-cherry, #5358). The \"-ly\"\n    is what says the word is about the state rather than a thing, so \"im genuinely exausted\"\n    reads without anybody naming \"genuinely\" here.\n    "))?; __attrs_823.dict_set(Value::from("__defaults__"), Value::tuple(__signature_820.defaults.clone()))?; let __kwdefaults_824 = Value::dict(); __attrs_823.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_819 = Frame::module(frame.globals.clone()); let mut __function_821 = NativeFunction::qualified_with_origin("_measures_a_state".into(), "_measures_a_state".into(), "bot.understanding.normalize".into(), __attrs_823, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/understanding/normalize.py", first: 1595, last: 1608, qualname: "_measures_a_state" }, closure: __closure_819.clone(), freevars: vec![] }, move |rt, args| __py_54::_measures_a_state(rt, __closure_819.clone(), &__signature_820, args)); __function_821 })?;
frame.store("_a_letter_typed_twice", { let __signature_826 = Signature { name: "_a_letter_typed_twice".into(), positional: vec!["word".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_828 = Value::dict(); __attrs_828.dict_set(Value::from("__doc__"), Value::from("The feeling a word is when one of its letters was typed twice, or None.\n\n    \"im saad\", \"im maad\", \"im loow\", \"im shyy\", \"im lonelyy\": the letter that came out twice is\n    one letter too many, and the word without it is a feeling. The one-edit reader in\n    `_one_letter_apart` refuses these on purpose - a letter typed into a word only counts when it\n    is a vowel, and a four letter word needs its feeling to be longer than it is, because a word\n    that short is as often a name - and the doubled letter is not always a vowel (\"lonelyy\").\n    Nothing is lost by reading the one slip on its own terms: the word being read is not in the\n    lexicon, and the word without the doubled letter is a feeling and not a name.\n    "))?; __attrs_828.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_829 = Value::dict(); __attrs_828.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_825 = Frame::module(frame.globals.clone()); let mut __function_827 = NativeFunction::qualified_with_origin("_a_letter_typed_twice".into(), "_a_letter_typed_twice".into(), "bot.understanding.normalize".into(), __attrs_828, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/understanding/normalize.py", first: 1611, last: 1630, qualname: "_a_letter_typed_twice" }, closure: __closure_825.clone(), freevars: vec![] }, move |rt, args| __py_55::_a_letter_typed_twice(rt, __closure_825.clone(), &__signature_826, args)); __function_827 })?;
