frame.store("_an_introduction", { let __default_847 = Value::None; let __default_848 = Value::None; let __signature_845 = Signature { name: "_an_introduction".into(), positional: vec!["before".into(),"before_before".into(),"after".into(),"before_words".into(),"after_words".into()], positional_only: 0, defaults: vec![__default_847,__default_848], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_849 = Value::dict(); __attrs_849.dict_set(Value::from("__doc__"), Value::from("True when this word is the name a line introduces rather than a state it states.\n\n    The five shapes are the ones a person gives their name in, and none of them is a shape a\n    feeling comes in: a greeting in front of it, \"this is X\", an \"X here\" or \"X from <place>\"\n    tail, an age after it, or a word at the front of the line that the verb after it has as its\n    subject (\"saad is my brother\"): a state is what a line says about somebody, not what it\n    says about a word.\n    "))?; __attrs_849.dict_set(Value::from("__defaults__"), Value::tuple(__signature_845.defaults.clone()))?; let __kwdefaults_850 = Value::dict(); __attrs_849.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_844 = Frame::module(frame.globals.clone()); let mut __function_846 = NativeFunction::qualified_with_origin("_an_introduction".into(), "_an_introduction".into(), "bot.understanding.normalize".into(), __attrs_849, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/understanding/normalize.py", first: 1646, last: 1671, qualname: "_an_introduction" }, closure: __closure_844.clone(), freevars: vec![] }, move |rt, args| __py_56::_an_introduction(rt, __closure_844.clone(), &__signature_845, args)); __function_846 })?;
