frame.store("_a_letter_wrong_in_a_state", { let __signature_859 = Signature { name: "_a_letter_wrong_in_a_state".into(), positional: vec!["word".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_861 = Value::dict(); __attrs_861.dict_set(Value::from("__doc__"), Value::from("The one state word `word` is a letter away from, or None.\n\n    This is a whole-letter test, not the vowel-only one `_a_slip_of_a_state` makes, and it is\n    only asked where the line itself says the word is how the person is: a letter typed wrong\n    is the ordinary slip of a state word (\"hungy\", \"thisty\", \"colde\"), and the state list is\n    the closed one, so nothing else in the language is a letter from one of them. The word has\n    to be the last word of the clause as well, because \"been staring at a screen all day\" is a\n    letter from \"starving\" and is not about hunger at all.\n    "))?; __attrs_861.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_862 = Value::dict(); __attrs_861.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_858 = Frame::module(frame.globals.clone()); let mut __function_860 = NativeFunction::qualified_with_origin("_a_letter_wrong_in_a_state".into(), "_a_letter_wrong_in_a_state".into(), "bot.understanding.normalize".into(), __attrs_861, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/understanding/normalize.py", first: 1684, last: 1702, qualname: "_a_letter_wrong_in_a_state" }, closure: __closure_858.clone(), freevars: vec![] }, move |rt, args| __py_57::_a_letter_wrong_in_a_state(rt, __closure_858.clone(), &__signature_859, args)); __function_860 })?;
frame.store("_a_letter_apart", { let __signature_864 = Signature { name: "_a_letter_apart".into(), positional: vec!["word".into(),"other".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_866 = Value::dict(); __attrs_866.dict_set(Value::from("__doc__"), Value::from("True when one letter added, left out, doubled or swapped round makes the other word.\n\n    This is the feeling rule's own test (`_one_letter_apart`) with the consonant let in: people\n    do type \"hungy\" for hungry and \"thisty\" for thirsty, a consonant left out in the middle,\n    and \"dizzzy\" with one letter doubled. A letter on the front or the end of a whole word is\n    still not a slip, which is what keeps \"im busy\" out of it.\n    "))?; __attrs_866.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_867 = Value::dict(); __attrs_866.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_863 = Frame::module(frame.globals.clone()); let mut __function_865 = NativeFunction::qualified_with_origin("_a_letter_apart".into(), "_a_letter_apart".into(), "bot.understanding.normalize".into(), __attrs_866, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/understanding/normalize.py", first: 1705, last: 1718, qualname: "_a_letter_apart" }, closure: __closure_863.clone(), freevars: vec![] }, move |rt, args| __py_58::_a_letter_apart(rt, __closure_863.clone(), &__signature_864, args)); __function_865 })?;
frame.store("_near_a_feeling", { let __default_871 = Value::None; let __default_872 = Value::None; let __default_873 = Value::None; let __default_874 = Value::Bool(false); let __default_875 = Value::None; let __default_876 = Value::None; let __signature_869 = Signature { name: "_near_a_feeling".into(), positional: vec!["word".into(),"before".into(),"before_before".into(),"after".into(),"alone".into(),"before_words".into(),"after_words".into()], positional_only: 0, defaults: vec![__default_871,__default_872,__default_873,__default_874,__default_875,__default_876], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_877 = Value::dict(); __attrs_877.dict_set(Value::from("__doc__"), Value::from("The feeling a misspelt feeling word names, or None.\n\n    A feeling word is a closed list, so one letter out is still that feeling: \"knackerd\" is\n    \"knackered\", \"shatterd\" is \"shattered\", \"worrid\" is \"worried\", \"exausted\" is\n    \"exhausted\". This is the class a general spell-fixer has to refuse, because next to an\n    ordinary word the shortest edit is another ordinary word; next to a feeling word there is\n    nothing to confuse it with. A word that could be two feelings is left alone.\n\n    Only where a state can stand: after a be-form, with at most one measure word between (\"im so\n    exausted\", \"she was knackerd\", \"i feel awsome\"). Every other feeling repair in this file is\n    framed like that and this one was not, so a real word the lexicon does not hold became the\n    feeling anywhere in the line: \"how do i change a nappy\" was read as \"snappy\" (four deck\n    lines, and the question reached the pool for a short temper), \"my nappy bag is heavy\" as\n    \"snappy bag\". The frame is the second guard, after the lexicon.\n    "))?; __attrs_877.dict_set(Value::from("__defaults__"), Value::tuple(__signature_869.defaults.clone()))?; let __kwdefaults_878 = Value::dict(); __attrs_877.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_868 = Frame::module(frame.globals.clone()); let mut __function_870 = NativeFunction::qualified_with_origin("_near_a_feeling".into(), "_near_a_feeling".into(), "bot.understanding.normalize".into(), __attrs_877, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/understanding/normalize.py", first: 1721, last: 1789, qualname: "_near_a_feeling" }, closure: __closure_868.clone(), freevars: vec![] }, move |rt, args| __py_59::_near_a_feeling(rt, __closure_868.clone(), &__signature_869, args)); __function_870 })?;
frame.store("_a_consonant_left_out_of_an_ing_word", { let __signature_880 = Signature { name: "_a_consonant_left_out_of_an_ing_word".into(), positional: vec!["word".into(),"feeling".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_882 = Value::dict(); __attrs_882.dict_set(Value::from("__doc__"), Value::from("True when the only difference is a consonant missing from a word ending in \"-ing\".\n\n    A vowel is what people leave out of an \"-ing\" word when the keys are under the fingers\n    (\"starvng\", \"annoyng\", \"depresing\"), so a vowel is the whole of the slip the frame and the\n    closed feeling list were built to catch. A consonant left out of an \"-ing\" word is an\n    ordinary verb underneath instead, and the feeling on the list is another word: \"staring\" is\n    \"stare\" with \"-ing\" on it and only the \"v\" of \"starving\" makes it a state, so \"been staring\n    at a screen all day\" was read as \"been starving at a screen all day\". The frame cannot see\n    the difference - \"ive been exausted\" and \"ive been staring\" stand in the same place - so the\n    letter is what decides.\n    "))?; __attrs_882.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_883 = Value::dict(); __attrs_882.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_879 = Frame::module(frame.globals.clone()); let mut __function_881 = NativeFunction::qualified_with_origin("_a_consonant_left_out_of_an_ing_word".into(), "_a_consonant_left_out_of_an_ing_word".into(), "bot.understanding.normalize".into(), __attrs_882, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/understanding/normalize.py", first: 1792, last: 1809, qualname: "_a_consonant_left_out_of_an_ing_word" }, closure: __closure_879.clone(), freevars: vec![] }, move |rt, args| __py_60::_a_consonant_left_out_of_an_ing_word(rt, __closure_879.clone(), &__signature_880, args)); __function_881 })?;
frame.store("_the_state_is_the_whole_frame", { let __default_887 = Value::None; let __signature_885 = Signature { name: "_the_state_is_the_whole_frame".into(), positional: vec!["before".into(),"before_before".into(),"before_words".into()], positional_only: 0, defaults: vec![__default_887], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_888 = Value::dict(); __attrs_888.dict_set(Value::from("__doc__"), Value::from("True when nothing but the person or the be-form stands in front of the state.\n\n    Two letters out is a long enough slip for two different words to be that close, and a state\n    said of a thing is where the two meet: \"my phone screen is cracked\" is a screen, \"cracked\"\n    being \"crackered\" by two letters. So this repair only reaches a line whose subject is the\n    person - \"im stessd\", \"im so stessd\", \"she was stessd\" - and stands down the moment a thing is\n    named in front of the be-form (\"my phone screen is cracked\", \"the table leg is cracked\").\n    "))?; __attrs_888.dict_set(Value::from("__defaults__"), Value::tuple(__signature_885.defaults.clone()))?; let __kwdefaults_889 = Value::dict(); __attrs_888.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_884 = Frame::module(frame.globals.clone()); let mut __function_886 = NativeFunction::qualified_with_origin("_the_state_is_the_whole_frame".into(), "_the_state_is_the_whole_frame".into(), "bot.understanding.normalize".into(), __attrs_888, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/understanding/normalize.py", first: 1812, last: 1826, qualname: "_the_state_is_the_whole_frame" }, closure: __closure_884.clone(), freevars: vec![] }, move |rt, args| __py_61::_the_state_is_the_whole_frame(rt, __closure_884.clone(), &__signature_885, args)); __function_886 })?;
