frame.store("_docs_doctor", { let __signature_3222 = Signature { name: "_docs_doctor".into(), positional: vec!["clean".into(),"words".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_3224 = Value::dict(); __attrs_3224.dict_set(Value::from("__doc__"), Value::from("\"Docs\" is read as the doctor where the line is about the surgery, and left as it is.\n\n    Only the two spellings people type for it, `doc` and `docs`, and only when a verb of going\n    or ringing is within a few words on either side and the line names no paperwork at all. A\n    line naming neither stays as typed: guessing one way would be worse than not guessing.\n\n    It is the one repair made in `clean` rather than only in `plain`, because no table anywhere\n    is keyed on \"docs\": the health answers hold \"doctor\" and the paperwork ones hold \"pdf\",\n    \"folder\", \"invoice\". Repairing `plain` alone moves the reading and leaves the reply alone,\n    which is where this line stood. The usual cost of repairing `clean` - a cue list that holds\n    the typed form loses its match - cannot be paid here, because no list holds this one.\n    "))?; __attrs_3224.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_3225 = Value::dict(); __attrs_3224.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_3221 = Frame::module(frame.globals.clone()); let mut __function_3223 = NativeFunction::qualified_with_origin("_docs_doctor".into(), "_docs_doctor".into(), "bot.understanding.normalize".into(), __attrs_3224, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/understanding/normalize.py", first: 5546, last: 5583, qualname: "_docs_doctor" }, closure: __closure_3221.clone(), freevars: vec![] }, move |rt, args| __py_170::_docs_doctor(rt, __closure_3221.clone(), &__signature_3222, args)); __function_3223 })?;
